            rep.check(sec is not None and lo <= sec <= hi, f"{name}: RestartSec must be a time span between {lo}s and {hi}s (got {rs!r})")
        for sec_, key in (("Unit", "After"), ("Unit", "Before"), ("Unit", "Requires"), ("Unit", "Wants")):
