            if rule.get("pidfile"):
                rep.check(pf == rule["pidfile"], f"{name}: PIDFile must be {rule['pidfile']}")
        if rule.get("user") is not None:
            rep.check(one(secs, "Service", "User") == rule["user"], f"{name}: User must be {rule['user']!r} (got {one(secs, 'Service', 'User')!r})")
        if rule.get("restart"):
