            if d.year in ys and d.month in ms and d.day in ds and (dow is None or d.weekday() in dow):
                for h in hs:
                    for m in mi:
                        t = d.replace(hour=h, minute=m)
                        if start <= t < end:
                            out.add(t)
            d += dt.timedelta(days=1)
    return out


